.libPaths(c(file.path(Sys.getenv('HOME'),'R/x86_64-pc-linux-gnu-library/4.5'),.libPaths()))
suppressPackageStartupMessages({library(data.table);library(Matrix);library(UCell)})
setDTthreads(1);o='results/mp10_section_specificity_pearson_v1';x=as(readMM(file.path(o,'scores/sc_temporary.mtx')),'CsparseMatrix');g=readLines(file.path(o,'scores/sc_genes.txt'));m=fread(file.path(o,'tables/sc_cells.tsv'));dimnames(x)=list(g,m$cell)
if(anyDuplicated(g)){u=unique(g);x=sparseMatrix(i=match(g,u),j=seq_along(g),x=1)%*%x;rownames(x)=u}
gs=fread(file.path(o,'tables/gene_sets.tsv'));sets=lapply(split(gs$gene_symbol,gs$gs_name),unique);aliases=c(CCN2='CTGF',CAVIN3='PRKCDBP',ACKR3='CXCR7');sets=lapply(sets,function(z){for(i in seq_along(z))if(!z[i]%in%rownames(x)&&z[i]%in%names(aliases)&&aliases[z[i]]%in%rownames(x))z[i]=aliases[z[i]];intersect(unique(z),rownames(x))})
u=ScoreSignatures_UCell(x,features=sets,name=NULL,ncores=1,chunk.size=100,maxRank=1500,ties.method='average');a=cbind(m,as.data.table(u[m$cell,,drop=FALSE]));l=melt(a,id.vars=names(m),variable.name='program',value.name='UCell');s=l[,.(n_cells=.N,mean=mean(UCell),median=median(UCell),q25=quantile(UCell,.25),q75=quantile(UCell,.75)),by=.(dataset,sample,type,lineage,program)];fwrite(s,file.path(o,'tables/sc_sample_program_source.tsv.gz'),sep='\t')
new=unique(gs[grepl('^BUDDEN_',gs_name),gene_symbol]);new=intersect(new,rownames(x));expr=as.matrix(x[new,,drop=FALSE]);lib=Matrix::colSums(x);norm=log1p(sweep(expr,2,lib,'/')*1e4);out=list();for(lin in unique(m$lineage)){ix=which(m$lineage==lin);out[[lin]]=data.table(lineage=lin,gene=new,n_cells=length(ix),detected_fraction=rowMeans(expr[,ix,drop=FALSE]>0),mean_logCP10k=rowMeans(norm[,ix,drop=FALSE]))};fwrite(rbindlist(out),file.path(o,'tables/sc_new5_gene_source.tsv'),sep='\t');message('SC source complete')
